import { useEffect, useId, useRef } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { DISMISS_REASONS, type DismissReason } from './trialEnd.js';
import styles from './WhyNotNow.module.css';

/**
 * "Why not now?" (sales plan A): the one optional question when a
 * full-screen offer is put away. Four answers, one tap each, and Skip;
 * either closes the screen at once. The answer rides on the offer's
 * `dismissed` event as `reason` and nothing else is asked or stored.
 */
export function WhyNotNow({
  titleId,
  onAnswer,
}: {
  titleId: string;
  /** The answer, or undefined for Skip. */
  onAnswer: (reason: DismissReason | undefined) => void;
}): React.JSX.Element {
  const groupId = useId();
  const first = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    first.current?.focus();
  }, []);
  return (
    <div className={styles.ask}>
      <span className={styles.mark} aria-hidden="true">
        <Icon name="heart" size={22} />
      </span>
      <h2 id={titleId} className={styles.title}>
        {t('whyNot.title')}
      </h2>
      <p className={styles.lead} id={groupId}>
        {t('whyNot.lead')}
      </p>
      <div className={styles.reasons} role="group" aria-labelledby={`${titleId} ${groupId}`}>
        {DISMISS_REASONS.map((reason, index) => (
          <button
            key={reason}
            ref={index === 0 ? first : undefined}
            type="button"
            className={styles.reason}
            onClick={() => {
              onAnswer(reason);
            }}
          >
            <span>{t(`whyNot.${reason}`)}</span>
            <Icon name="chevronRight" size={18} weight={2} className={styles.chevron} />
          </button>
        ))}
      </div>
      <button
        type="button"
        className={styles.skip}
        onClick={() => {
          onAnswer(undefined);
        }}
      >
        {t('whyNot.skip')}
      </button>
    </div>
  );
}
